/* Auto-hidden controls */
input, select, button, textarea, label, fieldset,
.dg, .lil-gui, .qs_main, .opc-container, .opc-gui, .quicksettings, .p5DomElement {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;
    position: absolute !important;
    left: -9999px !important;
    top: -9999px !important;
    width: 0px !important;
    height: 0px !important;
}

code:
/**
 * ============================================================================
 * 視覺藝術作品署名與靈感宣告 (ATTRIBUTION & INSPIRATION DECLARATION)
 * ============================================================================
 * 作者 (Author / Code Adaptor): Uncler M
 * 靈感啟發來源 (Inspired By): Concentric Sound - "Processing 声音可视化 Concentric Sound"
 * 原始作品討論 (Original Note): http://xhslink.com/o/8mFpKjxm3RN
 * 授權協議 (License): Creative Commons Attribution-NonCommercial-ShareAlike 4.0 (CC BY-NC-SA 4.0)
 * 
 * [說明 / Notice]
 * 本作品由 Uncler M 編寫與視聽化對應。演算法靈感取材自 Concentric Sound 創作之
 * 「中心聲音心跳波紋與多重同心圓聲波擴散場」視覺概念。
 * 專為 4K MV Visual Integration Editor 專案打造。
 * ============================================================================
 */

let waveRings = [];
let heartbeatPhase = 0;

let smoothedSubBass = 0.0;
let smoothedPercussive = 0.0;
let smoothedMid = 0.0;

setup = () => {
  p5.disableFriendlyErrors = true;
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 1.0);
  ellipseMode(CENTER);

  // 初始化基礎同心圓佇列
  for (let i = 0; i < 14; i++) {
    waveRings.push({
      r: i * 35 + 40,
      maxR: max(width, height) * 0.75,
      speed: 1.5 + i * 0.2,
      harmonics: int(random(4, 12)),
      hueOffset: i * 15
    });
  }
};

draw = () => {
  // 1. 動態音訊信號平滑處理
  let rawSubBass = (typeof sub_bass !== 'undefined') ? sub_bass : (typeof sub_bass_ratio !== 'undefined' ? sub_bass_ratio : (mouseIsPressed ? 0.85 : 0.22));
  let rawPercussive = (typeof percussive !== 'undefined') ? percussive : (mouseIsPressed ? 0.9 : 0.1);
  let rawMid = (typeof mid !== 'undefined') ? mid : (typeof mid_ratio !== 'undefined' ? mid_ratio : 0.3);

  smoothedSubBass += (rawSubBass - smoothedSubBass) * 0.14;
  smoothedPercussive += (rawPercussive - smoothedPercussive) * 0.28;
  smoothedMid += (rawMid - smoothedMid) * 0.18;

  heartbeatPhase += 0.03 + smoothedSubBass * 0.08;

  // 2. 聲波擴散背景
  background(225, 45, 6, 0.24);

  let cx = width * 0.5;
  let cy = height * 0.5;
  let currentHue = (typeof chord_hue !== 'undefined' && chord_hue > 0) ? chord_hue : 175;

  // 3. 重拍觸發「聲波擴散極光爆發 (Sound Wave Burst)」
  if (smoothedPercussive > 0.65 && random() < 0.3) {
    let burstRings = int(random(2, 5));
    for (let b = 0; b < burstRings; b++) {
      waveRings.push({
        r: 30 + b * 20,
        maxR: max(width, height) * 0.8,
        speed: random(4.0, 9.0),
        harmonics: int(random(6, 16)),
        hueOffset: random(-40, 40)
      });
    }
  }

  // 4. 更新與繪製多重同心圓聲波 (Concentric Wave Propagation Rings)
  noFill();

  for (let i = waveRings.length - 1; i >= 0; i--) {
    let ring = waveRings[i];
    ring.r += ring.speed * (1.0 + smoothedSubBass * 1.5);

    if (ring.r > ring.maxR) {
      if (waveRings.length > 14) {
        waveRings.splice(i, 1);
        continue;
      } else {
        ring.r = 30;
      }
    }

    let alpha = map(ring.r, 30, ring.maxR, 0.9, 0.02);
    let ringHue = (currentHue + ring.hueOffset + map(ring.r, 30, ring.maxR, 0, 120)) % 360;

    stroke(ringHue, 80, 95, alpha);
    strokeWeight(Math.max(0.1, Math.abs(1.2 + (1.0 - ring.r / ring.maxR))) * 3.5 + smoothedSubBass * 2.5);

    // 繪製具備幾何諧波與波形褶皺的同心圓 (Harmonic Deformed Wave Ring)
    beginShape();
    let numSteps = 120;
    for (let s = 0; s <= numSteps; s++) {
      let a = (TWO_PI / numSteps) * s;
      let sineHarmonic = sin(a * ring.harmonics + heartbeatPhase) * (8.0 + smoothedMid * 25.0);
      let noiseVal = (noise(cos(a) * 1.5 + 2, sin(a) * 1.5 + 2, heartbeatPhase * 0.5) - 0.5) * 30.0 * smoothedMid;

      let rFinal = ring.r + sineHarmonic + noiseVal;
      let px = cx + rFinal * cos(a);
      let py = cy + rFinal * sin(a);

      vertex(px, py);
    }
    endShape(CLOSE);
  }

  // 5. 中心聲音心跳震盪核 (Central Waveform Heartbeat Core)
  let coreRadius = (35.0 + sin(heartbeatPhase * 2) * 12.0 + smoothedSubBass * 75.0 + smoothedPercussive * 40.0);

  // 外圍發光心跳暈 (Glow Halo)
  noStroke();
  fill((currentHue + 40) % 360, 85, 100, 0.35 + smoothedPercussive * 0.4);
  ellipse(cx, cy, coreRadius * 2.2, coreRadius * 2.2);

  // 核心心跳波形體
  fill((currentHue + 80) % 360, 40, 100, 0.95);
  ellipse(cx, cy, coreRadius, coreRadius);
};

